mapper.select:
 SELECT * FROM
		boards b LEFT JOIN users u ON u.user_id = b.user_id LEFT JOIN trip_plans
		tp ON tp.trip_plan_id = b.trip_plan_id 

				AND (
				b.title LIKE CONCAT('%', #{keyword}, '%')
				OR b.content LIKE CONCAT('%', #{keyword}, '%')
				)


				AND b.content_type = #{contentType}


		ORDER BY b.board_id DESC LIMIT #{limit} OFFSET #{offset}
